## Demonstration
## ---------------------------------------------------------------------------
if (identical(environment(), globalenv()) && !interactive()) {
  mod <- pdt_model()
  cat("\n== CALIBRATION ==\n");  print(PDT_calibration_report(mod), right = FALSE)
  cat("\n== PPD DECOMPOSITION ==\n"); print(PDT_decompose(mod), right = FALSE)
  cd <- PDT_critical_depth(mod)
  cat("\n== CRITICAL PROBING DEPTH ==\n")
  cat(sprintf("  SRP      : %.2f mm (Lindhe 1982: ~2.9 mm)\n", attr(cd,"critical_PD_SRP")))
  cat(sprintf("  Surgery  : %.2f mm (Lindhe 1982: ~4.2 mm)\n", attr(cd,"critical_PD_SURGERY")))
  cat(sprintf("  Crossover: %.2f mm (surgery overtakes SRP)\n", attr(cd,"SRP_SURG_crossover")))
  cat("\n== SEPARATRIX ==\n"); print(PDT_separatrix(mod))
  cat("\n== SUBVERSION COUNTERFACTUAL ==\n")
  print(PDT_subversion_counterfactual(mod), right = FALSE)
  cat("\n== TIMING ==\n"); print(PDT_timing(mod), right = FALSE)
}
